const LEVEL = "level1";
const JSONL_PATH = "C:\\Users\\marco\\data\\knowledge\\level1-cps.jsonl";
const DB_PATH = "C:\\Users\\marco\\data\\db\\level1-cps.json";
const DB_KEY = "persistence_db_level1_cps";
const MAX_RECORDS = 1000;

function parsePayload(payload) {
    if (!payload) return {};
    if (typeof payload === "string") {
        try { return JSON.parse(payload); } catch (err) { return { raw: payload }; }
    }
    if (Buffer.isBuffer(payload)) {
        try { return JSON.parse(payload.toString()); } catch (err) { return { raw: payload.toString() }; }
    }
    return payload && typeof payload === "object" ? payload : { raw: payload };
}

function normalizeId(value) {
    return String(value || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "").replace(/(cps)0+/, "$1");
}

function inferKind(topic) {
    if (topic.endsWith("/oee") || topic.endsWith("/data")) return "observed";
    if (topic.endsWith("/local/adaptive")) return "knowledge";
    return null;
}

const topic = String(msg.topic || "").trim();
const source = normalizeId(topic.split("/")[0]);
const kind = inferKind(topic);
if (!source.startsWith("cps") || !kind) return null;

const payload = parsePayload(msg.payload);
const now = Date.now();
const timestamp = payload.timestamp || new Date(now).toISOString();
const ts = Number(payload.ts || Date.parse(timestamp) || now);
const messageType = payload.messageType || (kind === "knowledge" ? "cps_adaptive_local_intelligence" : topic.endsWith("/oee") ? "cps_oee_observation" : "cps_data_observation");
const record = {
    id: LEVEL + "-" + kind + "-" + source + "-" + ts,
    level: LEVEL,
    kind,
    source: payload.source || payload.cpsId || source,
    topic,
    messageType,
    ts,
    timestamp,
    payload
};

const records = Array.isArray(global.get(DB_KEY)) ? global.get(DB_KEY) : [];
const nextRecords = records.concat(record).slice(-MAX_RECORDS);
global.set(DB_KEY, nextRecords);
node.status({ fill: kind === "knowledge" ? "blue" : "green", shape: "dot", text: source + " " + kind + " | " + nextRecords.length });

return [
    { payload: JSON.stringify(record), filename: JSONL_PATH },
    { payload: JSON.stringify({ records: nextRecords }, null, 2), filename: DB_PATH }
];

const LEVEL = "level2";
const JSONL_PATH = "C:\\Users\\marco\\data\\knowledge\\level2-acsm.jsonl";
const DB_PATH = "C:\\Users\\marco\\data\\db\\level2-acsm.json";
const DB_KEY = "persistence_db_level2_acsm";
const MAX_RECORDS = 1000;

function parsePayload(payload) {
    if (!payload) return {};
    if (typeof payload === "string") {
        try { return JSON.parse(payload); } catch (err) { return { raw: payload }; }
    }
    if (Buffer.isBuffer(payload)) {
        try { return JSON.parse(payload.toString()); } catch (err) { return { raw: payload.toString() }; }
    }
    return payload && typeof payload === "object" ? payload : { raw: payload };
}

function inferKind(topic) {
    if (/^acsm[123]\/level2\/intelligence$/.test(topic)) return "observed";
    if (/^acsm[123]\/local\/adaptive$/.test(topic)) return "knowledge";
    return null;
}

const topic = String(msg.topic || "").trim();
const source = topic.split("/")[0] || "acsm";
const kind = inferKind(topic);
if (!kind) return null;

const payload = parsePayload(msg.payload);
const now = Date.now();
const timestamp = payload.timestamp || new Date(now).toISOString();
const ts = Number(payload.ts || Date.parse(timestamp) || now);
const messageType = payload.messageType || (kind === "knowledge" ? "acsm_local_adaptive_intelligence" : "acsm_level2_intelligence");
const record = {
    id: LEVEL + "-" + kind + "-" + source + "-" + ts,
    level: LEVEL,
    kind,
    source: payload.source || payload.acsmId || source,
    topic,
    messageType,
    ts,
    timestamp,
    payload
};

const records = Array.isArray(global.get(DB_KEY)) ? global.get(DB_KEY) : [];
const nextRecords = records.concat(record).slice(-MAX_RECORDS);
global.set(DB_KEY, nextRecords);
node.status({ fill: kind === "knowledge" ? "blue" : "green", shape: "dot", text: source + " " + kind + " | " + nextRecords.length });

return [
    { payload: JSON.stringify(record), filename: JSONL_PATH },
    { payload: JSON.stringify({ records: nextRecords }, null, 2), filename: DB_PATH }
];

const rawLimit = Number(msg.req?.query?.limit || 25);
msg.historyLevel = "level1";
msg.historyFile = "C:\\Users\\marco\\data\\knowledge\\level1-cps.jsonl";
msg.historyLimit = Math.min(Math.max(Number.isFinite(rawLimit) ? rawLimit : 25, 1), 200);
msg.filename = msg.historyFile;
return msg;

const rawLimit = Number(msg.req?.query?.limit || 25);
msg.historyLevel = "level2";
msg.historyFile = "C:\\Users\\marco\\data\\knowledge\\level2-acsm.jsonl";
msg.historyLimit = Math.min(Math.max(Number.isFinite(rawLimit) ? rawLimit : 25, 1), 200);
msg.filename = msg.historyFile;
return msg;

function extractAdaptive(payload) {
    const candidates = [
        payload?.adaptiveLearningCps,
        payload?.adaptiveLearningLocal,
        payload?.adaptiveLearningService,
        payload?.adaptiveLearning,
        payload?.raw?.adaptiveLearning
    ];
    return candidates.find((item) => item && typeof item === "object") || {};
}

function parseLines(raw) {
    if (!raw || typeof raw !== "string") return [];
    return raw
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter(Boolean)
        .map((line) => {
            try { return JSON.parse(line); } catch (err) { return null; }
        })
        .filter(Boolean);
}

function isMissingFileError(message, code) {
    const text = String(message || "").toLowerCase();
    const errorCode = String(code || "").toLowerCase();
    return errorCode.includes("enoent") || text.includes("enoent") || text.includes("no such file");
}

const limit = Math.min(Math.max(Number(msg.historyLimit || msg.req?.query?.limit || 25), 1), 200);
const level = msg.historyLevel || "unknown";
const file = msg.historyFile || msg.filename || "";
const details = msg.error?.message || msg.error?.toString?.() || "";
const code = msg.error?.code || msg.error?.source?.type || "";

msg.headers = {
    "content-type": "application/json",
    "access-control-allow-origin": "*"
};

if (msg.error) {
    if (isMissingFileError(details, code)) {
        msg.statusCode = 200;
        msg.payload = {
            ok: true,
            level,
            file,
            limit,
            count: 0,
            records: []
        };
        return msg;
    }

    msg.statusCode = 500;
    msg.payload = {
        ok: false,
        level,
        file,
        error: "Failed to read history file",
        details: details || "Unknown file read error"
    };
    return msg;
}

const records = parseLines(String(msg.payload || ""))
    .sort((a, b) => Number(b.ts || Date.parse(b.timestamp) || 0) - Number(a.ts || Date.parse(a.timestamp) || 0))
    .slice(0, limit)
    .map((record) => {
        const adaptive = extractAdaptive(record.payload || {});
        return {
            ...record,
            temporalState: adaptive.temporalState || "",
            adaptiveAction: adaptive.adaptiveAction || ""
        };
    });

msg.statusCode = 200;
msg.payload = {
    ok: true,
    level,
    file,
    limit,
    count: records.length,
    records
};
return msg;
